import{_ as r,o as t,c as s,ag as a}from"./chunks/framework.DQQHyi2x.js";const v=JSON.parse('{"title":"MCP Servers","description":"","frontmatter":{},"headers":[],"relativePath":"features/mcp-servers.md","filePath":"features/mcp-servers.md"}'),o={name:"features/mcp-servers.md"};function i(l,e,n,d,c,h){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="mcp-servers" tabindex="-1">MCP Servers <a class="header-anchor" href="#mcp-servers" aria-label="Permalink to &quot;MCP Servers&quot;">​</a></h1><p>Manage Model Context Protocol servers — the integrations that give Claude access to external tools, resources, and prompts.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The MCP Servers page has two tabs:</p><ul><li><strong>My Servers</strong> — view and manage all configured MCP servers</li><li><strong>Registry</strong> — browse and install servers from the <a href="https://registry.modelcontextprotocol.io" target="_blank" rel="noreferrer">MCP Registry</a></li></ul><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="viewing-servers" tabindex="-1">Viewing Servers <a class="header-anchor" href="#viewing-servers" aria-label="Permalink to &quot;Viewing Servers&quot;">​</a></h3><p>The My Servers tab shows all configured servers as cards displaying:</p><ul><li>Server name and connection status (connected, failed, needs-auth, not-tested)</li><li>Transport type (stdio command or HTTP/SSE URL)</li><li>Scope badge (user, project, plugin, or managed)</li><li>Tool, resource, and prompt counts (from cached test results)</li><li>Enable/disable toggle</li></ul><h3 id="adding-a-server" tabindex="-1">Adding a Server <a class="header-anchor" href="#adding-a-server" aria-label="Permalink to &quot;Adding a Server&quot;">​</a></h3><p>Click <strong>&quot;Add Server&quot;</strong> to open the wizard:</p><ol><li>Enter a server name</li><li>Choose the transport type: <ul><li><strong>stdio</strong> — command-based servers (e.g., <code>node</code>, <code>npx</code>, <code>python</code>)</li><li><strong>http</strong> — HTTP POST JSON-RPC servers (supports OAuth tokens)</li><li><strong>sse</strong> — Server-Sent Events servers</li></ul></li><li>Configure connection details (command + args for stdio, URL for http/sse)</li><li>Optionally set environment variables and headers</li><li>Choose the scope (user or project)</li></ol><h3 id="testing-servers" tabindex="-1">Testing Servers <a class="header-anchor" href="#testing-servers" aria-label="Permalink to &quot;Testing Servers&quot;">​</a></h3><p>Click the <strong>test button</strong> on a server card or use <strong>&quot;Test All&quot;</strong> to verify connectivity. Testing:</p><ul><li>Verifies the command or URL is reachable</li><li>Communicates via the MCP JSON-RPC protocol</li><li>Discovers available tools, resources, and prompts</li><li>Caches results for display on the card and detail view</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Tests have a 30-second timeout. npx-based servers may need extra startup time.</p></div><h3 id="server-detail-view" tabindex="-1">Server Detail View <a class="header-anchor" href="#server-detail-view" aria-label="Permalink to &quot;Server Detail View&quot;">​</a></h3><p>Click a server card to see full details:</p><ul><li>Complete configuration (command, arguments, environment variables)</li><li>Cached connection test results</li><li>Lists of discovered tools, resources, and prompts (up to 200 items)</li><li>Server version and capabilities</li><li>Approval settings override</li></ul><h3 id="server-approval-settings" tabindex="-1">Server Approval Settings <a class="header-anchor" href="#server-approval-settings" aria-label="Permalink to &quot;Server Approval Settings&quot;">​</a></h3><p>Expand the <strong>Approval Settings</strong> panel to configure how Claude handles tool approvals:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th></tr></thead><tbody><tr><td>Ask every time</td><td>Prompt before each tool use (default)</td></tr><tr><td>Always allow</td><td>Auto-approve all tool calls</td></tr><tr><td>Always deny</td><td>Block all tool calls</td></tr></tbody></table><p>Per-server overrides let you set different policies for individual servers.</p><h3 id="browsing-the-registry" tabindex="-1">Browsing the Registry <a class="header-anchor" href="#browsing-the-registry" aria-label="Permalink to &quot;Browsing the Registry&quot;">​</a></h3><p>Switch to the <strong>Registry</strong> tab to discover pre-built MCP servers. You can browse by category, search by name, and install servers directly into your configuration.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>MCP servers are stored in two locations:</p><table tabindex="0"><thead><tr><th>File</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><code>~/.claude.json</code></td><td>User</td><td>Global MCP servers</td></tr><tr><td><code>.mcp.json</code></td><td>Project</td><td>Project-specific servers</td></tr></tbody></table><p>Plugin-provided and managed (enterprise) servers are read-only and shown with distinct badges.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Use <strong>project-scoped</strong> servers for tools specific to a codebase (e.g., database access).</li><li>Use <strong>user-scoped</strong> servers for tools you want everywhere (e.g., web search).</li><li><strong>Test servers</strong> after adding them to verify connectivity and discover available tools.</li><li><strong>Managed servers</strong> (enterprise) appear with an amber badge and cannot be modified.</li><li>Environment variables in server configs are masked in the UI for security.</li></ul>',31)])])}const u=r(o,[["render",i]]);export{v as __pageData,u as default};
